export function validateFloorValue(floorValue: bigint): void {
  if (floorValue < MIN_FLOOR_VALUE || floorValue > MAX_FLOOR_VALUE) throw new RangeError("floor value out of range");
}

/* Lamports the whole float is worth at `tick`, given its value at tick 0. Same arithmetic as the program. */
export function valueAtTick(floorValue: bigint, tick: number): bigint {
  const m = MULT[tick];
  if (!Number.isInteger(tick) || m === undefined) throw new RangeError("tick out of range");
  validateFloorValue(floorValue);
  return (floorValue * m) >> SCALE_BITS;
}

/* Value at the top of the grid, tick MAX_TICK: the most a launch can raise (there is no cap). */
export function gridTop(floorValue: bigint): bigint {
  return valueAtTick(floorValue, MAX_TICK);
}

/* Highest tick whose float value is at most `maxValue`; null when even tick 0 is above it. */
export function tickForMaxValue(floorValue: bigint, maxValue: bigint): number | null {
  validateFloorValue(floorValue);
  if (maxValue < floorValue) return null;
  let lo = 0;
  let hi = MAX_TICK;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo + 1) / 2);
    if (valueAtTick(floorValue, mid) <= maxValue) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

